        h.size = arr.length;
        for (int i = arr.length / 2 - 1; i >= 0; i--) {
            h.heapify(i);
        }
        return h;
    }

    // --- Static sort ---

    public static <T extends Comparable<T>> void sort(T[] arr) {
        sort(arr, Comparator.<T>naturalOrder());
    }

    public static <T> void sort(T[] arr, Comparator<T> comparator) {
        MinHeap<T> h = from(arr, comparator);
        for (int i = 0; i < arr.length; i++) {
            arr[i] = h.extractMin();
        }
    }

    // --- Internal helpers ---

    @SuppressWarnings("unchecked")
    private T at(int i) {
        return (T) heap[i];
    }

    private int compare(int a, int b) {
        return comparator.compare(at(a), at(b));
    }

    private void swap(int a, int b) {
        Object temp = heap[a];
        heap[a] = heap[b];
        heap[b] = temp;
    }

    private int parent(int i) { return (i - 1) / 2; }
    private int left(int i)   { return 2 * i + 1; }
    private int right(int i)  { return 2 * i + 2; }

    private void grow() {
        heap = Arrays.copyOf(heap, heap.length * 2);
    }

    private void requireValidIndex(int i) {
        if (i < 0 || i >= size)
            throw new IndexOutOfBoundsException("Index " + i + " out of bounds for size " + size);
    }

    // Iterative sift-down — equivalent to the tail-recursive form but avoids call-stack growth.
    private void heapify(int i) {
        while (true) {
            int l = left(i);
            int r = right(i);
            int smallest = i;
            if (l < size && compare(l, smallest) < 0) smallest = l;
            if (r < size && compare(r, smallest) < 0) smallest = r;
            if (smallest == i) break;
            swap(i, smallest);
            i = smallest;
        }
    }

    // --- Mutation ---

    public void insert(T key) {
        if (size == heap.length) grow();
        int i = size;
        heap[i] = key;
        size++;
        while (i != 0 && compare(i, parent(i)) < 0) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

    public void decreaseKey(int i, T newVal) {
        requireValidIndex(i);
        heap[i] = newVal;
        while (i != 0 && compare(i, parent(i)) < 0) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

    public void increaseKey(int i, T newVal) {
        requireValidIndex(i);
        heap[i] = newVal;
        heapify(i);
    }

    public void changeKey(int i, T newVal) {
        requireValidIndex(i);
        int cmp = comparator.compare(at(i), newVal);
        if (cmp == 0) return;
        if (cmp < 0) increaseKey(i, newVal);
        else decreaseKey(i, newVal);
    }

    public boolean remove(T value) {
        for (int i = 0; i < size; i++) {
            if (comparator.compare(at(i), value) == 0) {
                removeAt(i);
                return true;
            }
        }
        return false;
    }

    public void clear() {
        Arrays.fill(heap, 0, size, null);
        size = 0;
    }

    public void removeAt(int i) {
        requireValidIndex(i);
        heap[i] = heap[size - 1];
        heap[size - 1] = null;
        size--;
        if (size > 0 && i < size) {
            if (i > 0 && compare(i, parent(i)) < 0) {
                while (i != 0 && compare(i, parent(i)) < 0) {
                    swap(i, parent(i));
                    i = parent(i);
                }
            } else {
                heapify(i);
            }
        }
    }

    // --- Access ---

    public T getMin() {
        if (size == 0) throw new NoSuchElementException("Heap is empty");
        return at(0);
    }

    public T extractMin() {
        if (size == 0) throw new NoSuchElementException("Heap is empty");
        T root = at(0);
        size--;
        heap[0] = heap[size];
        heap[size] = null;
        heapify(0);
        return root;
    }

    public boolean contains(T value) {
        for (int i = 0; i < size; i++) {
            if (comparator.compare(at(i), value) == 0) return true;
        }
        return false;
    }

    // Returns the heap elements in heap order (not sorted).
    public Object[] toArray() {
        return Arrays.copyOf(heap, size);
    }

    // Returns the heap elements in sorted order without modifying this heap.
    public Object[] toSortedArray() {
        MinHeap<T> copy = new MinHeap<>(comparator, size);
        System.arraycopy(heap, 0, copy.heap, 0, size);
        copy.size = this.size;
        Object[] result = new Object[size];
        for (int i = 0; i < result.length; i++) {
            result[i] = copy.extractMin();
        }
        return result;
    }

    // --- Utility ---

    public boolean isEmpty() { return size == 0; }
    public int size()        { return size; }

    @Override
    public Iterator<T> iterator() {
        return new Iterator<T>() {
            private int cursor = 0;

            @Override
            public boolean hasNext() {
                return cursor < size;
            }

            @Override
            public T next() {
                if (!hasNext()) throw new NoSuchElementException();
                return at(cursor++);
            }
        };
    }

    @Override
    public String toString() {
        if (size == 0) return "[]";
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < size; i++) {
            if (i > 0) sb.append(", ");
            sb.append(at(i));
        }
        return sb.append("]").toString();
    }
}

